import json, re
# Strict marker-required accuracy across checkpoints (the prompt-instructed #### convention)
def strict_acc(path):
    n=0; c=0
    with open(path) as f:
        for line in f:
            r=json.loads(line); n+=1
            out=r['output']; gt=r['gts']
            m = re.findall(r'####\s*(\-?[0-9\.\,]+)', out)
            ans=None
            if m: ans = m[-1].replace(',','').replace('\$','').strip()
            elif '\\\\boxed' in out:
                b=re.findall(r'\\\\boxed\{([^{}]*)\}', out); ans=b[-1].replace(',','').replace('\$','').strip() if b else None
            if ans is not None:
                try:
                    if abs(float(ans)-float(gt))<1e-6: c+=1
                except: pass
    return c/n
for step in [0,10,20,30,40,50,60]:
    print(f'step {step}: strict(marker-required) acc = {strict_acc(f\"val_generations/{step}.jsonl\"):.4f}')
"

